// Move a character one square at a time, stopping at walls and waiting until each step is
// finished.
// grid-movement: original MIT-licensed native educational port.
// Generated by tools/ports/generate.py; edit the specification to preserve parity.
// Input: [width,height,step_seconds,repeat_delay,repeat_interval,buffer_seconds,dt,direction,...9_
// state_values,...row_major_grid]
// Output: [...9_next_state_values,visual_x,visual_y,steps_started,tiles_arrived,blocked_flag]
// Persistent one-update controller. Directions 0=release,1=up,2=right,3=down,4=left (Y down).
// State: tile_x,tile_y,target_x,target_y,progress,buffered_direction,held_direction,repeat_remaini
// ng,buffer_remaining. Keep the first nine outputs for the next call. Zero tiles are walkable. dt
// is 0..1 seconds; repeat delay/interval >=0.01 seconds. See README for event ordering and static-
// map assumptions; [-1] means invalid configuration/state.
// Precondition: finite, correctly shaped data; integer indices/counts/IDs.
// See ../PORTS.md for examples, limits, and the shared test fixtures.

#![allow(unused_assignments, unused_mut, dead_code, unused_parens)]
// Count how many numbers are in this list.
fn port_length(a: &[f64]) -> f64 { a.len() as f64 }
// Read one number at a zero-based position; stop if that position does not exist.
fn port_get(a: &[f64], i:f64) -> f64 { assert!(i.is_finite() && i>=0.0 && i.fract()==0.0 && i<(a.len() as f64)); a[i as usize] }
// Choose the smaller of two numbers.
fn port_minimum(a:f64,b:f64)->f64 { a.min(b) }
// Choose the larger of two numbers.
fn port_maximum(a:f64,b:f64)->f64 { a.max(b) }
// Round down to a whole number; minus 0.1 becomes minus 1.
fn port_floor_num(a:f64)->f64 { a.floor() }
// Remove a negative sign so a distance or size is not negative.
fn port_abs_num(a:f64)->f64 { a.abs() }

// 1. Read one direction: up, right, down, left, or no button.
// 2. Check the next square. Stay put if it is outside the map or contains a wall.
// 3. Either jump straight to that square or slide to it over the chosen step time.
// 4. Remember the newest direction briefly if it is pressed during a step. Try it after landing.
// 5. Holding a direction waits for a short delay, then requests more steps at regular times.
// Releasing stops those repeats.
pub fn compute(data: &[f64]) -> Vec<f64> {
    let mut w: f64 = 0.0;
    let mut h: f64 = 0.0;
    let mut step_seconds: f64 = 0.0;
    let mut repeat_delay: f64 = 0.0;
    let mut repeat_interval: f64 = 0.0;
    let mut buffer_seconds: f64 = 0.0;
    let mut remaining: f64 = 0.0;
    let mut direction: f64 = 0.0;
    let mut tile_x: f64 = 0.0;
    let mut tile_y: f64 = 0.0;
    let mut target_x: f64 = 0.0;
    let mut target_y: f64 = 0.0;
    let mut progress: f64 = 0.0;
    let mut buffered: f64 = 0.0;
    let mut held: f64 = 0.0;
    let mut repeat_remaining: f64 = 0.0;
    let mut buffer_remaining: f64 = 0.0;
    let mut started: f64 = 0.0;
    let mut arrived: f64 = 0.0;
    let mut blocked: f64 = 0.0;
    let mut visual_x: f64 = 0.0;
    let mut visual_y: f64 = 0.0;
    let mut advance: f64 = 0.0;
    let mut nx: f64 = 0.0;
    let mut ny: f64 = 0.0;
    let mut passable: f64 = 0.0;
    if (port_length(&data) < 18.0) {
        return vec![-(1.0)];
    }
    w = port_get(&data, 0.0);
    h = port_get(&data, 1.0);
    step_seconds = port_get(&data, 2.0);
    repeat_delay = port_get(&data, 3.0);
    repeat_interval = port_get(&data, 4.0);
    buffer_seconds = port_get(&data, 5.0);
    remaining = port_get(&data, 6.0);
    direction = port_get(&data, 7.0);
    tile_x = port_get(&data, 8.0);
    tile_y = port_get(&data, 9.0);
    target_x = port_get(&data, 10.0);
    target_y = port_get(&data, 11.0);
    progress = port_get(&data, 12.0);
    buffered = port_get(&data, 13.0);
    held = port_get(&data, 14.0);
    repeat_remaining = port_get(&data, 15.0);
    buffer_remaining = port_get(&data, 16.0);
    if ((w < 1.0) || (h < 1.0) || (port_floor_num(w) != w) || (port_floor_num(h) != h) || (port_length(&data) != (17.0 + (w * h)))) {
        return vec![-(1.0)];
    }
    if ((step_seconds < 0.0) || (repeat_delay < 0.01) || (repeat_interval < 0.01) || (buffer_seconds < 0.0) || (remaining < 0.0) || (remaining > 1.0)) {
        return vec![-(1.0)];
    }
    if ((direction < 0.0) || (direction > 4.0) || (port_floor_num(direction) != direction) || (held < 0.0) || (held > 4.0) || (port_floor_num(held) != held) || (buffered < 0.0) || (buffered > 4.0) || (port_floor_num(buffered) != buffered)) {
        return vec![-(1.0)];
    }
    if ((tile_x < 0.0) || (tile_x >= w) || (tile_y < 0.0) || (tile_y >= h) || (target_x < 0.0) || (target_x >= w) || (target_y < 0.0) || (target_y >= h)) {
        return vec![-(1.0)];
    }
    if ((port_floor_num(tile_x) != tile_x) || (port_floor_num(tile_y) != tile_y) || (port_floor_num(target_x) != target_x) || (port_floor_num(target_y) != target_y)) {
        return vec![-(1.0)];
    }
    if ((progress < 0.0) || (progress > 1.0) || (repeat_remaining < 0.0) || (buffer_remaining < 0.0) || ((port_abs_num((target_x - tile_x)) + port_abs_num((target_y - tile_y))) > 1.0)) {
        return vec![-(1.0)];
    }
    if (((target_x == tile_x) && (target_y == tile_y) && (progress != 0.0)) || (port_get(&data, ((17.0 + (tile_y * w)) + tile_x)) != 0.0) || (port_get(&data, ((17.0 + (target_y * w)) + target_x)) != 0.0)) {
        return vec![-(1.0)];
    }
    // Instant mode cannot resume a previously unfinished smooth step.
    if ((step_seconds == 0.0) && ((target_x != tile_x) || (target_y != tile_y))) {
        return vec![-(1.0)];
    }
    // A changed direction is a fresh press; a release stops repeating but keeps a live buffer.
    if (direction != held) {
        held = direction;
        repeat_remaining = 0.0;
        if (direction != 0.0) {
            repeat_remaining = repeat_delay;
            buffered = direction;
            buffer_remaining = buffer_seconds;
        }
    }
    started = 0.0;
    arrived = 0.0;
    blocked = 0.0;
    // Process exact event boundaries so a long update does not skip repeats or overshoot tiles.
    while (1.0 == 1.0) {
        if (((target_x != tile_x) || (target_y != tile_y)) && (progress >= (1.0 - 1e-09))) {
            tile_x = target_x;
            tile_y = target_y;
            progress = 0.0;
            arrived += 1.0;
        }
        if ((held != 0.0) && (repeat_remaining <= 1e-09)) {
            buffered = held;
            buffer_remaining = buffer_seconds;
            repeat_remaining += repeat_interval;
        }
        if ((tile_x == target_x) && (tile_y == target_y) && (buffered != 0.0)) {
            nx = tile_x;
            ny = tile_y;
            if (buffered == 1.0) {
                ny -= 1.0;
            }
            if (buffered == 2.0) {
                nx += 1.0;
            }
            if (buffered == 3.0) {
                ny += 1.0;
            }
            if (buffered == 4.0) {
                nx -= 1.0;
            }
            // Consume each request once, including a blocked request.
            buffered = 0.0;
            buffer_remaining = 0.0;
            passable = 0.0;
            if ((nx >= 0.0) && (nx < w) && (ny >= 0.0) && (ny < h)) {
                if (port_get(&data, ((17.0 + (ny * w)) + nx)) == 0.0) {
                    passable = 1.0;
                }
            }
            if (passable == 0.0) {
                blocked = 1.0;
            } else {
                target_x = nx;
                target_y = ny;
                started += 1.0;
                if (step_seconds == 0.0) {
                    tile_x = target_x;
                    tile_y = target_y;
                    arrived += 1.0;
                }
            }
        }
        if (remaining <= 1e-09) {
            break;
        }
        advance = remaining;
        if (held != 0.0) {
            advance = port_minimum(advance, repeat_remaining);
        }
        if ((tile_x != target_x) || (tile_y != target_y)) {
            advance = port_minimum(advance, ((1.0 - progress) * step_seconds));
            progress += (advance / step_seconds);
        }
        remaining = port_maximum(0.0, (remaining - advance));
        if (held != 0.0) {
            repeat_remaining = port_maximum(0.0, (repeat_remaining - advance));
        }
        if (buffered != 0.0) {
            buffer_remaining -= advance;
            // A buffer remains valid at its exact deadline, but expires strictly after it.
            if (buffer_remaining < -(1e-09)) {
                buffered = 0.0;
                buffer_remaining = 0.0;
            } else {
                buffer_remaining = port_maximum(0.0, buffer_remaining);
            }
        }
    }
    visual_x = (tile_x + ((target_x - tile_x) * progress));
    visual_y = (tile_y + ((target_y - tile_y) * progress));
    return vec![tile_x, tile_y, target_x, target_y, progress, buffered, held, repeat_remaining, buffer_remaining, visual_x, visual_y, started, arrived, blocked];
}
